      success: { bg: "rgba(20,60,30,0.92)", border: "#4caf50" },
      warn: { bg: "rgba(60,50,20,0.92)", border: "#ff9800" },
      error: { bg: "rgba(60,20,30,0.92)", border: "#e53935" }
