function updateLandingStats(state) {
  _landingState = state;
  const $ = (id) => document.getElementById(id);
  const neurons = state.totalNeurons ?? state.neurons ?? 1e3;
  const psi = state.psi ?? 0;
  const arousal = state.arousal ?? state.amygdala?.arousal ?? state.sharedMood?.arousal ?? 0;
  const valence = state.valence ?? state.amygdala?.valence ?? state.sharedMood?.valence ?? 0;
  const coherence = state.oscillations?.coherence ?? state.sharedMood?.coherence ?? 0;
  const spikes = state.spikeCount ?? state.totalSpikes ?? 0;
  const users = state.connectedUsers ?? 0;
  const el = (id, text) => {
    const e = $(id);
    if (e) e.textContent = text;
  };
  el("ls-neurons", neurons.toLocaleString() + " real neurons");
  el("ls-psi", "\u03A8 = " + psi.toFixed(4));
  el("ls-users", users + " online");
  el("ls-arousal", (arousal * 100).toFixed(0) + "%");
  el("ls-valence", valence.toFixed(3));
  el("ls-coherence", (coherence * 100).toFixed(0) + "%");
  el("ls-spikes", spikes.toString());
  if (state.perf) {
    el("ls-cpu", state.perf.cpuPercent + "%");
    el("ls-gpu", state.perf.gpuUtilPercent + "%");
  }
  const minGrade = state.minGrade || "\u2014";
  const gradeEl = $("ls-grade");
  if (gradeEl) {
    gradeEl.textContent = minGrade;
    if (minGrade === "pre-K") gradeEl.style.color = "#ef4444";
    else if (minGrade === "K" || minGrade === "grade1" || minGrade === "grade2") gradeEl.style.color = "#f59e0b";
    else if (minGrade === "unknown" || minGrade === "\u2014") gradeEl.style.color = "#555";
    else gradeEl.style.color = "#22c55e";
  }
  const _cur = state.curriculum;
  if (_cur && _cur.perSubject) {
    const ps = _cur.perSubject;
    const parts = [];
    for (const sub of ["ela", "math", "science", "social", "art", "life"]) {
      const e = ps[sub];
      if (!e) continue;
      const name = e.courseName || sub;
      const gr = e.grade || "\u2014";
      parts.push(`${name} (${gr})`);
    }
    if (parts.length) el("ls-grade-per-subject", parts.join(" \xB7 "));
  } else if (state.grades) {
    const g = state.grades;
    const line = `ela:${g.ela || "\u2014"} \xB7 math:${g.math || "\u2014"} \xB7 sci:${g.science || "\u2014"} \xB7 soc:${g.social || "\u2014"} \xB7 art:${g.art || "\u2014"} \xB7 life:${g.life || "\u2014"}`;
    el("ls-grade-per-subject", line);
  }
}
