  const valenceVal = $("hud-valence");
  if (valenceVal) valenceVal.textContent = valence.toFixed(2);
  const cohBar = $("hud-coherence-bar");
  if (cohBar) cohBar.style.width = `${(coherence * 100).toFixed(0)}%`;
