      "pre-K": 4,
      "K": 5,
      "grade1": 6,
      "grade2": 7,
      "grade3": 8,
      "grade4": 9,
      "grade5": 10,
      "grade6": 11,
      "grade7": 12,
      "grade8": 13,
      "grade9": 14,
      "grade10": 15,
      "grade11": 16,
      "grade12": 17,
